  );
  TestValidator.equals(
    "moderator account status is active",
    moderator.account_status,
    "active",
  );
  TestValidator.equals(
    "moderator has full moderation tier",
    moderator.moderation_tier,
    "full",
  );

  // Step 2: Prepare rejection data
