  const rejectedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.reject(connection, {
      articleId: articleId,
      body: {
        rejectionReason: rejectionReason,
      } satisfies IDiscussionBoardArticle.IReject,
