  TestValidator.equals(
    "rejection reason matches moderator input",
    rejectedArticle.rejection_reason,
    rejectionReason,
  );

  // Step 6: Verify article ID matches the rejection request
  TestValidator.equals(
    "article ID matches rejection request",
    rejectedArticle.id,
    articleId,
  );

