    thirdLogin.account_status,
    "active",
  );

  // Step 9: Verify last_login_at is updated
  TestValidator.predicate(
    "last_login_at is set after login",
    firstLogin.last_login_at !== null && firstLogin.last_login_at !== undefined,
  );
}

