  const articleCreateBody = {
    title: articleTitle,
    content: articleContent,
    categoryId: categoryId,
    href: "http://localhost:3000/articles/create",
    referrer: "http://localhost:3000",
    attachments: [
      {
        original_filename: "test_document.pdf",
        file_type: "pdf",
        file_size: 1024000,
        mime_type: "application/pdf",
