  const mixedCaseQueries = [
    "TEST@EXAMPLE",
    "Hello-World",
    "QUERY_CASE",
  ] as const;

  for (const query of mixedCaseQueries) {
    const result: IPageIDiscussionBoardArticle.ISummary =
      await api.functional.discussionBoard.articles.index(connection, {
