  typia.assert(article);

  // 3. Test attachment of unsupported file types
  const unsupportedFileTypes = [
    {
      filename: "malware.exe",
      extension: "exe",
      mimeType: "application/x-msdownload",
      size: 1024,
    },
    {
      filename: "archive.zip",
