  const maxArticleAttachments = articleWithMaxAttachments.attachments!;
  maxArticleAttachments.forEach((attachment, index) => {
    TestValidator.equals(
      `attachment ${index} article reference`,
      attachment.discussion_board_article_id,
      articleWithMaxAttachments.id,
    );
