/**
 * Test MIME type validation for comment attachments to prevent format spoofing.
 *
 * This test validates that the attachment upload API enforces MIME type
 * matching against file extensions. The security measure prevents malicious
 * users from uploading files with mismatched MIME types and extensions (e.g.,
 * renaming a malicious PNG to have a JPG extension).
 *
 * Test flow:
 *
 * 1. Create a contributor account and authenticate
 * 2. Create an article for testing
 * 3. Create a comment on the article
 * 4. Attempt to upload attachment with JPG extension but PNG MIME type (should
 *    fail)
 * 5. Upload valid attachment with matching JPG extension and image/jpeg MIME type
 *    (should succeed)
 * 6. Verify the attachment is created with correct metadata
 */
export async function test_api_comment_attachment_mime_type_validation(
  connection: api.IConnection,
) {
  // 1. Create contributor account
  const contributor: IDiscussionBoardContributor.IAuthorized =
    await api.functional.auth.contributor.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
