  TestValidator.equals(
    "contributor created successfully",
    contributor.email_verified,
    false,
  );

  // 2. Create an article for testing comments
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.contributor.articles.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 3 }),
          content: RandomGenerator.content({ paragraphs: 2 }),
          categoryId: typia.random<string & tags.Format<"uuid">>(),
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(article);
  TestValidator.equals(
    "article created in draft status",
    article.status,
    "draft",
  );

  // 3. Create a comment on the article
  const comment: IDiscussionBoardComment =
    await api.functional.discussionBoard.contributor.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);
  TestValidator.equals(
    "comment created successfully",
    comment.is_deleted,
    false,
  );

  // 4. Attempt to upload attachment with mismatched MIME type (should fail)
  await TestValidator.error(
    "attachment with mismatched MIME type should be rejected",
    async () => {
      await api.functional.discussionBoard.contributor.articles.comments.attachments.create(
        connection,
        {
          articleId: article.id,
          commentId: comment.id,
          body: {
            original_file_name: "image.jpg",
            file_type: "jpg",
            file_size: 102400,
            mime_type: "image/png",
            display_url: typia.random<string & tags.Format<"uri">>(),
          } satisfies IDiscussionBoardCommentAttachment.ICreate,
        },
      );
    },
  );

  // 5. Upload valid attachment with matching MIME type and extension
  const validAttachment: IDiscussionBoardCommentAttachment =
    await api.functional.discussionBoard.contributor.articles.comments.attachments.create(
      connection,
      {
