  });

  // Step 13: Moderator approves and pins second article
  const pinnedArticle2 =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article2.id,
        body: {
          status: "published",
          is_pinned: true,
