import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test moderator ability to unpin a pinned article.
 *
 * Validates that a moderator can remove a pinned article from featured display
 * by setting is_pinned to false. Verifies the pin status change is properly
 * reflected in the article state and that unpinning is reversible.
 *
 * Workflow:
 *
 * 1. Create contributor and moderator accounts
 * 2. Contributor creates and submits article for approval
 * 3. Moderator approves and pins the article for featured display
 * 4. Verify article is pinned (is_pinned = true)
 * 5. Moderator unpins the article (is_pinned = false)
 * 6. Verify article is no longer pinned
 * 7. Moderator repins the article to verify reversibility
 * 8. Verify article is pinned again
 */
export async function test_api_article_moderator_unpin_article(
  connection: api.IConnection,
) {
  // Step 1: Create contributor account
  const contributorEmail = typia.random<string & tags.Format<"email">>();
  const contributor = await api.functional.auth.contributor.join(connection, {
    body: {
      email: contributorEmail,
      username: RandomGenerator.alphaNumeric(10),
      password: "SecurePass123!",
      href: "http://localhost:3000/register",
      referrer: "http://localhost:3000/home",
    } satisfies IDiscussionBoardContributor.ICreate,
  });
  typia.assert(contributor);

  // Step 2: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.alphaNumeric(10),
      password: "ModeratorPass123!",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // Step 3: Create article with a valid category ID
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  // Step 4: Contributor creates article
  const article =
    await api.functional.discussionBoard.contributor.articles.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 3,
            wordMin: 2,
            wordMax: 5,
          }),
          content: RandomGenerator.content({
            paragraphs: 3,
            sentenceMin: 8,
            sentenceMax: 12,
          }),
          categoryId: categoryId,
          href: "http://localhost:3000/articles/create",
          referrer: "http://localhost:3000/articles",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(article);
  TestValidator.equals(
    "article created in draft status",
    article.status,
    "draft",
  );

  // Step 5: Contributor submits article for approval
  const submittedArticle =
    await api.functional.discussionBoard.contributor.articles.update(
      connection,
      {
        articleId: article.id,
        body: {
          status: "pending_approval",
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(submittedArticle);
  TestValidator.equals(
    "article transitioned to pending_approval",
    submittedArticle.status,
    "pending_approval",
  );

  // Step 6: Switch to moderator account
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "ModeratorPass123!",
      href: "http://localhost:3000/moderator/login",
      referrer: "http://localhost:3000/moderator",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 7: Moderator approves and pins the article
  const pinnedArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          status: "published",
          is_pinned: true,
          approval_notes: "Excellent article. Pinning for featured display.",
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(pinnedArticle);
  TestValidator.equals("article published", pinnedArticle.status, "published");
  TestValidator.predicate(
    "article is pinned",
    pinnedArticle.is_pinned === true,
  );

  // Step 8: Moderator unpins the article
  const unpinnedArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          is_pinned: false,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(unpinnedArticle);
  TestValidator.predicate(
    "article is no longer pinned",
    unpinnedArticle.is_pinned === false,
  );
  TestValidator.equals(
    "article status remains published after unpin",
    unpinnedArticle.status,
    "published",
  );

  // Step 9: Verify unpinning is reversible - repin the article
  const repinnedArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          is_pinned: true,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(repinnedArticle);
  TestValidator.predicate(
    "article is pinned again after repin",
    repinnedArticle.is_pinned === true,
  );
  TestValidator.equals(
    "article status remains published after repin",
    repinnedArticle.status,
    "published",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that a moderator can unlock a locked article to re-enable new comments.
 *
 * This test validates the article locking and unlocking functionality in the
 * discussion board system. It verifies that moderators can lock articles to
 * prevent further comments, and then unlock them to restore normal discussion
 * activity. The test ensures that locking and unlocking are reversible
 * operations for proper article lifecycle management.
 *
 * Test workflow:
 *
 * 1. Create contributor account and authenticate
 * 2. Create article in draft status with required content
 * 3. Transition article to pending_approval for moderator review
 * 4. Create moderator account and authenticate
 * 5. Approve and publish the article
 * 6. Lock the article by setting is_locked to true
 * 7. Verify article is locked (is_locked = true)
 * 8. Unlock the article by setting is_locked to false
 * 9. Verify article is no longer locked and returns to normal state
 */
export async function test_api_article_moderator_unlock_article(
  connection: api.IConnection,
) {
  // Step 1: Create contributor account
  const contributorEmail = typia.random<string & tags.Format<"email">>();
  const contributor: IDiscussionBoardContributor.IAuthorized =
    await api.functional.auth.contributor.join(connection, {
      body: {
        email: contributorEmail,
        username: RandomGenerator.alphabets(10),
        password: "TestPassword123!",
        href: "http://localhost:3000/join",
        referrer: "http://localhost:3000",
      } satisfies IDiscussionBoardContributor.ICreate,
    });
  typia.assert(contributor);

  // Step 2: Get article categories for article creation
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  // Step 3: Create article in draft status
  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.contributor.articles.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({
            sentences: 3,
            wordMin: 3,
            wordMax: 5,
          }),
          content: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 5,
            sentenceMax: 10,
            wordMin: 3,
            wordMax: 6,
          }),
          categoryId: categoryId,
          href: "http://localhost:3000/articles/create",
          referrer: "http://localhost:3000",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(article);
  TestValidator.equals(
    "article created in draft status",
    article.status,
    "draft",
  );
  TestValidator.equals(
    "article initially not locked",
    article.is_locked,
    false,
  );

  // Step 4: Transition article to pending_approval
  const pendingArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.contributor.articles.update(
      connection,
      {
        articleId: article.id,
        body: {
          status: "pending_approval",
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(pendingArticle);
  TestValidator.equals(
    "article transitioned to pending_approval",
    pendingArticle.status,
    "pending_approval",
  );

  // Step 5: Create moderator account
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        username: RandomGenerator.alphabets(10),
        password: "ModeratorPass123!",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 6: Moderator logs in
  await api.functional.auth.moderator.login(connection, {
    body: {
      email: moderatorEmail,
      password: "ModeratorPass123!",
      href: "http://localhost:3000/login",
      referrer: "http://localhost:3000",
    } satisfies IDiscussionBoardModerator.ILogin,
  });

  // Step 7: Moderator approves and publishes the article
  const publishedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          status: "published",
          approval_notes: "Article meets community guidelines",
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(publishedArticle);
  TestValidator.equals(
    "article published by moderator",
    publishedArticle.status,
    "published",
  );

  // Step 8: Moderator locks the article
  const lockedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          is_locked: true,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(lockedArticle);
  TestValidator.equals("article is locked", lockedArticle.is_locked, true);
  TestValidator.equals(
    "locked article still published",
    lockedArticle.status,
    "published",
  );

  // Step 9: Verify locked article prevents comments (article is locked)
  TestValidator.predicate(
    "locked article is_locked flag true",
    lockedArticle.is_locked === true,
  );

  // Step 10: Moderator unlocks the article to re-enable comments
  const unlockedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      {
        articleId: article.id,
        body: {
          is_locked: false,
        } satisfies IDiscussionBoardArticle.IUpdate,
      },
    );
  typia.assert(unlockedArticle);
  TestValidator.equals("article is unlocked", unlockedArticle.is_locked, false);
  TestValidator.equals(
    "unlocked article remains published",
    unlockedArticle.status,
    "published",
  );

  // Step 11: Verify unlocked article returns to normal discussion state
  TestValidator.predicate(
    "unlocked article is_locked flag false",
    unlockedArticle.is_locked === false,
  );
  TestValidator.predicate(
    "unlocked article is in published status",
    unlockedArticle.status === "published",
  );

  // Step 12: Verify locking and unlocking are reversible operations
  TestValidator.notEquals(
    "locked and unlocked states are different",
    lockedArticle,
    unlockedArticle,
    (key) => key === "updated_at",
  );
  TestValidator.equals(
    "article ID remains same after lock/unlock",
    lockedArticle.id,
    unlockedArticle.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

export async function test_api_article_moderator_archive_published_article(
  connection: api.IConnection,
) {
  // Step 1: Create a contributor account to author an article
  const contributorEmail = typia.random<string & tags.Format<"email">>();
  const contributor = await api.functional.auth.contributor.join(connection, {
    body: {
      email: contributorEmail,
      username: RandomGenerator.alphabets(10),
      password: "TestPass123!",
      href: "http://localhost:3000/register",
      referrer: "http://localhost:3000",
    } satisfies IDiscussionBoardContributor.ICreate,
  });
  typia.assert(contributor);
  TestValidator.predicate(
    "contributor account is active",
    contributor.account_status === "active",
  );

  // Step 2: Create an article in draft status
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const articleCreate = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 2, wordMax: 5 }),
    content: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    categoryId: categoryId,
    href: "http://localhost:3000/articles/create",
    referrer: "http://localhost:3000",
  } satisfies IDiscussionBoardArticle.ICreate;

  const draftArticle =
    await api.functional.discussionBoard.contributor.articles.create(
      connection,
      {
        body: articleCreate,
      },
    );
  typia.assert(draftArticle);
  TestValidator.equals("article status is draft", draftArticle.status, "draft");

  // Step 3: Update article to pending_approval status
  const articleUpdate = {
    status: "pending_approval",
  } satisfies IDiscussionBoardArticle.IUpdate;

  const pendingArticle =
    await api.functional.discussionBoard.contributor.articles.update(
      connection,
      {
        articleId: draftArticle.id,
        body: articleUpdate,
      },
    );
  typia.assert(pendingArticle);
  TestValidator.equals(
    "article status is pending_approval",
    pendingArticle.status,
    "pending_approval",
  );

  // Step 4: Create a moderator account to approve and archive the article
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator = await api.functional.auth.moderator.join(connection, {
    body: {
      email: moderatorEmail,
      username: RandomGenerator.alphabets(10),
      password: "ModPass123!",
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);
  TestValidator.predicate(
    "moderator account is active",
    moderator.account_status === "active",
  );

  // Step 5: Moderator approves the article (transitions to published)
  const approvalUpdate = {
    status: "published",
    approval_notes: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IDiscussionBoardArticle.IUpdate;

  const publishedArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      { articleId: pendingArticle.id, body: approvalUpdate },
    );
  typia.assert(publishedArticle);
  TestValidator.equals(
    "article status is published",
    publishedArticle.status,
    "published",
  );
  TestValidator.predicate(
    "published_at timestamp is set after approval",
    publishedArticle.published_at !== null &&
      publishedArticle.published_at !== undefined,
  );

  // Step 6: Moderator archives the published article
  const archiveUpdate = {
    status: "archived",
  } satisfies IDiscussionBoardArticle.IUpdate;

  const archivedArticle =
    await api.functional.discussionBoard.moderator.articles.updateByModerator(
      connection,
      { articleId: publishedArticle.id, body: archiveUpdate },
    );
  typia.assert(archivedArticle);
  TestValidator.equals(
    "article status transitions to archived",
    archivedArticle.status,
    "archived",
  );

  // Step 7: Verify archived article maintains key metadata
  TestValidator.equals(
    "article ID preserved after archival",
    archivedArticle.id,
    publishedArticle.id,
  );
  TestValidator.equals(
    "article title preserved after archival",
    archivedArticle.title,
    publishedArticle.title,
  );
  TestValidator.equals(
    "article content preserved after archival",
    archivedArticle.content,
    publishedArticle.content,
  );
  TestValidator.equals(
    "published_at timestamp preserved after archival",
    archivedArticle.published_at,
    publishedArticle.published_at,
  );

  // Step 8: Verify article author information is maintained
  TestValidator.equals(
    "author ID preserved in archived article",
    archivedArticle.author.id,
    contributor.id,
  );
  TestValidator.equals(
    "author username preserved in archived article",
    archivedArticle.author.username,
    contributor.username,
  );

  // Step 9: Verify article properties after archival
  TestValidator.predicate(
    "archived article maintains creation timestamp",
    archivedArticle.created_at !== null &&
      archivedArticle.created_at !== undefined,
  );
  TestValidator.predicate(
    "archived article has updated_at timestamp",
    archivedArticle.updated_at !== null &&
      archivedArticle.updated_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
