      typia.assert(entry);
      TestValidator.equals(
        "audit log entry should have moderator property",
        entry.moderator !== undefined,
        true,
      );
      TestValidator.equals(
        "audit log entry moderator ID should match filter",
        entry.moderator.id,
        moderator1.id,
      );
    }
