  // Step 2: Test valid limit value = 1
  const resultLimit1: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(resultLimit1);
  TestValidator.equals(
    "limit 1 pagination limit field",
    resultLimit1.pagination.limit,
    1,
  );
  TestValidator.predicate(
    "limit 1 returns valid pagination",
    resultLimit1.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit 1 data array is valid",
    Array.isArray(resultLimit1.data),
  );

  // Step 3: Test valid limit value = 20
  const resultLimit20: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(resultLimit20);
  TestValidator.equals(
    "limit 20 pagination limit field",
    resultLimit20.pagination.limit,
    20,
  );
  TestValidator.predicate(
    "limit 20 data length valid",
    resultLimit20.data.length <= 20,
  );

  // Step 4: Test valid limit value = 50
  const resultLimit50: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(resultLimit50);
  TestValidator.equals(
    "limit 50 pagination limit field",
    resultLimit50.pagination.limit,
    50,
  );
  TestValidator.predicate(
    "limit 50 data length valid",
    resultLimit50.data.length <= 50,
  );

  // Step 5: Test valid limit value = 100 (maximum)
  const resultLimit100: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(resultLimit100);
  TestValidator.equals(
    "limit 100 pagination limit field",
    resultLimit100.pagination.limit,
    100,
  );
  TestValidator.predicate(
    "limit 100 data length valid",
    resultLimit100.data.length <= 100,
  );

  // Step 6: Test invalid limit value = 0 (below minimum)
  await TestValidator.error("limit 0 should be rejected", async () => {
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 0,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  });

  // Step 7: Test invalid limit value = 101 (above maximum)
  await TestValidator.error("limit 101 should be rejected", async () => {
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 101,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  });

  // Step 8: Verify pagination metadata structure across different limits
  TestValidator.predicate(
    "limit 1 pagination has current field",
    resultLimit1.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit 1 pagination has records field",
    resultLimit1.pagination.records >= 0,
  );
  TestValidator.predicate(
    "limit 1 pagination has pages field",
    resultLimit1.pagination.pages >= 0,
  );

  TestValidator.predicate(
    "limit 100 pagination has current field",
    resultLimit100.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit 100 pagination has records field",
    resultLimit100.pagination.records >= 0,
  );
  TestValidator.predicate(
    "limit 100 pagination has pages field",
    resultLimit100.pagination.pages >= 0,
  );

  // Step 9: Verify consistent response structure
  TestValidator.predicate(
    "limit 1 data is array",
    Array.isArray(resultLimit1.data),
  );
  TestValidator.predicate(
    "limit 100 data is array",
    Array.isArray(resultLimit100.data),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardAccountRestriction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAccountRestriction";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardAccountRestriction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAccountRestriction";

/**
 * Test search parameter with various string lengths.
 *
 * This test validates that the search parameter length constraint is properly
 * enforced when querying account restrictions. The endpoint accepts search
 * queries up to 500 characters (as defined by MaxLength<500> in
 * IDiscussionBoardAccountRestriction.IRequest.search), and should reject
 * queries exceeding this limit.
 *
 * Test flow:
 *
 * 1. Authenticate as a moderator
 * 2. Test search with single character query (valid, minimum)
 * 3. Test search with typical keyword (valid, normal case)
 * 4. Test search with 500-character query (valid, maximum)
 * 5. Test search with 501+ character query (invalid, exceeds maximum)
 * 6. Validate that all valid searches return proper paginated results
 * 7. Validate that invalid search lengths are rejected
 */
export async function test_api_moderation_restrictions_search_query_length(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: moderatorEmail,
        password: "Test@Password123",
        username: RandomGenerator.alphaNumeric(10),
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // Step 2: Test search with single character query (valid, minimum)
  const singleCharQuery = "a";
  const result1: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          search: singleCharQuery,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(result1);
  TestValidator.predicate(
    "single character search should return valid paginated results",
    result1.pagination !== null && typeof result1.pagination === "object",
  );

  // Step 3: Test search with typical keyword (valid, normal case)
  const typicalKeyword = RandomGenerator.paragraph({ sentences: 1 });
  const result2: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          search: typicalKeyword,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(result2);
  TestValidator.predicate(
    "typical keyword search should return valid paginated results",
    result2.pagination !== null && typeof result2.pagination === "object",
  );

  // Step 4: Test search with 500-character query (valid, maximum)
  const maxLengthQuery = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 50,
    sentenceMax: 60,
    wordMin: 2,
    wordMax: 3,
  }).substring(0, 500);

  const result3: IPageIDiscussionBoardAccountRestriction =
    await api.functional.discussionBoard.moderator.moderation.restrictions.index(
      connection,
      {
        body: {
          search: maxLengthQuery,
        } satisfies IDiscussionBoardAccountRestriction.IRequest,
      },
    );
  typia.assert(result3);
  TestValidator.equals(
    "500-character search should have correct query length",
    maxLengthQuery.length,
    500,
  );
  TestValidator.predicate(
    "maximum length search should return valid paginated results",
    result3.pagination !== null && typeof result3.pagination === "object",
  );

  // Step 5: Test search with 501+ character query (invalid, exceeds maximum)
  const exceedsMaxQuery = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 60,
    sentenceMax: 70,
    wordMin: 2,
    wordMax: 3,
  }).substring(0, 501);

  await TestValidator.error(
    "search with 501+ characters should fail validation",
    async () => {
      await api.functional.discussionBoard.moderator.moderation.restrictions.index(
        connection,
        {
          body: {
            search: exceedsMaxQuery,
          } satisfies IDiscussionBoardAccountRestriction.IRequest,
        },
      );
    },
  );

  // Step 6: Validate pagination structure for valid searches
  TestValidator.equals(
    "pagination should have current property",
    typeof result1.pagination.current,
    "number",
  );
  TestValidator.equals(
    "pagination should have limit property",
    typeof result1.pagination.limit,
    "number",
  );
  TestValidator.equals(
    "pagination should have records property",
    typeof result1.pagination.records,
    "number",
  );
  TestValidator.equals(
    "pagination should have pages property",
    typeof result1.pagination.pages,
    "number",
  );

  // Step 7: Verify data array exists
  TestValidator.predicate(
    "result should contain data array",
    Array.isArray(result1.data),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardUserSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserSuspension";

/**
 * Test creating a posting restriction suspension for a minor violation (first
 * offense).
 *
 * This test validates the moderator's ability to suspend a contributor's
 * posting capabilities while maintaining their login access. The scenario
 * involves:
 *
 * 1. A moderator registering their account
 * 2. A contributor being identified (using random UUID for testing)
 * 3. Moderator issuing a posting restriction suspension with minor severity and
 *    3-day duration
 * 4. Validation of the suspension record containing correct enforcement parameters
 *
 * The test ensures that:
 *
 * - Suspension is created with posting_restriction type (prevents article/comment
 *   posting)
 * - Severity level is set to "minor" for first-time violations
 * - Duration is 3 days with proper expiration timestamp calculation
 * - Suspension reason is documented for transparency
 * - Suspension status is "active" and immediately effective
 * - Response includes moderator and contributor information
 */
export async function test_api_contributor_suspension_posting_restriction_minor(
  connection: api.IConnection,
) {
  // 1. Moderator registration for authentication
  const moderator: IDiscussionBoardModerator.IAuthorized =
    await api.functional.auth.moderator.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        username: RandomGenerator.alphabets(10),
        password: "SecurePass123!",
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderator);

  // 2. Create a suspension for a contributor with posting restriction (minor violation)
  const contributorId = typia.random<string & tags.Format<"uuid">>();

  const suspension: IDiscussionBoardUserSuspension =
    await api.functional.discussionBoard.moderator.contributors.suspend.create(
      connection,
      {
        contributorId: contributorId,
        body: {
          suspension_type: "posting_restriction",
          severity_level: "minor",
          duration_days: 3,
          reason:
            "First-time violation: Inappropriate content in article posting. User suspended from creating new articles and comments for 3 days to prevent further violations.",
        } satisfies IDiscussionBoardUserSuspension.ICreate,
      },
    );
  typia.assert(suspension);

  // 3. Validate suspension record properties
  TestValidator.equals(
    "suspension type is posting_restriction",
    suspension.suspension_type,
    "posting_restriction",
  );

  TestValidator.equals(
    "severity level is minor",
    suspension.severity_level,
    "minor",
  );

  TestValidator.equals("duration is 3 days", suspension.duration_days, 3);

  TestValidator.equals(
    "suspension status is active",
    suspension.status,
    "active",
  );

  TestValidator.predicate(
    "contributor ID matches in suspension record",
    suspension.contributor.id === contributorId,
  );

  TestValidator.predicate(
