  TestValidator.equals(
    "article created in draft status",
    article.status,
    "draft",
  );
  TestValidator.equals(
    "article has zero comments initially",
    article.comment_count,
    0,
  );
  TestValidator.equals(
    "article has zero views initially",
    article.view_count,
    0,
  );

  // Step 3: Upload attachments to the article
  const attachment1FileName = `test-attachment-${RandomGenerator.alphaNumeric(8)}.jpg`;
  const attachment1 =
    await api.functional.discussionBoard.contributor.articles.attachments.attach(
      connection,
      {
        articleId: article.id,
        body: {
          original_filename: attachment1FileName,
          file_type: "jpg",
          file_size: 1024 * 50,
          mime_type: "image/jpeg",
          display_url: "http://localhost/storage/attachments/test-image-1.jpg",
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment1);

  const attachment2FileName = `document-${RandomGenerator.alphaNumeric(8)}.pdf`;
  const attachment2 =
    await api.functional.discussionBoard.contributor.articles.attachments.attach(
      connection,
      {
        articleId: article.id,
        body: {
          original_filename: attachment2FileName,
          file_type: "pdf",
          file_size: 1024 * 100,
          mime_type: "application/pdf",
          display_url:
            "http://localhost/storage/attachments/test-document-1.pdf",
        } satisfies IDiscussionBoardArticleAttachment.ICreate,
      },
    );
  typia.assert(attachment2);

  // Step 4: Register second contributor to add comments
  const commenter1Email = typia.random<string & tags.Format<"email">>();
  const commenter1Username = RandomGenerator.name(1);
  const commenter1 = await api.functional.auth.contributor.join(connection, {
    body: {
      email: commenter1Email,
      username: commenter1Username,
      password: "SecurePass123!@",
      href: "http://localhost/register",
      referrer: "http://localhost",
    } satisfies IDiscussionBoardContributor.ICreate,
  });
  typia.assert(commenter1);

  // Step 5: Add comments to the article (as commenter1)
  const comment1Data = {
    content: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 3,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment1 =
    await api.functional.discussionBoard.contributor.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: comment1Data,
      },
    );
  typia.assert(comment1);

  const comment2Data = {
    content: RandomGenerator.paragraph({
      sentences: 4,
      wordMin: 3,
      wordMax: 8,
    }),
  } satisfies IDiscussionBoardComment.ICreate;

  const comment2 =
    await api.functional.discussionBoard.contributor.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: comment2Data,
      },
    );
  typia.assert(comment2);

  // Step 6: Register third contributor for additional comments
  const commenter2Email = typia.random<string & tags.Format<"email">>();
  const commenter2Username = RandomGenerator.name(1);
  const commenter2 = await api.functional.auth.contributor.join(connection, {
    body: {
      email: commenter2Email,
      username: commenter2Username,
      password: "SecurePass123!@",
      href: "http://localhost/register",
      referrer: "http://localhost",
    } satisfies IDiscussionBoardContributor.ICreate,
  });
  typia.assert(commenter2);

  // Step 7: Add comments with attachments (as commenter2)
  const comment3Data = {
    content: RandomGenerator.paragraph({
      sentences: 6,
      wordMin: 3,
      wordMax: 8,
    }),
    attachments: [
      {
        original_file_name: `comment-image-${RandomGenerator.alphaNumeric(6)}.png`,
        file_type: "png",
        file_size: 1024 * 20,
        mime_type: "image/png",
        display_url: "http://localhost/storage/comment-attachments/image-1.png",
      } satisfies IDiscussionBoardCommentAttachment.ICreate,
    ],
  } satisfies IDiscussionBoardComment.ICreate;

  const comment3 =
    await api.functional.discussionBoard.contributor.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: comment3Data,
      },
    );
  typia.assert(comment3);
  TestValidator.predicate(
    "comment has attachments",
    comment3.attachments.length > 0,
  );

  // Step 8: Re-authenticate as article owner for deletion
  const ownerReauth = await api.functional.auth.contributor.join(connection, {
    body: {
      email: ownerEmail,
      username: ownerUsername,
      password: "SecurePass123!@",
      href: "http://localhost/login",
      referrer: "http://localhost",
    } satisfies IDiscussionBoardContributor.ICreate,
  });
  typia.assert(ownerReauth);

  // Step 9: Delete the article as owner
  const deletedArticle =
    await api.functional.discussionBoard.contributor.articles.erase(
      connection,
      {
        articleId: article.id,
      },
    );
  typia.assert(deletedArticle);
  TestValidator.equals(
    "article status is deleted after erase",
    deletedArticle.status,
    "deleted",
  );
  TestValidator.predicate(
    "article deleted_at timestamp is set",
    deletedArticle.deleted_at !== null &&
      deletedArticle.deleted_at !== undefined,
  );

  // Step 10: Verify cascade deletion - comment count cleared
  TestValidator.equals(
    "article comment_count reset to zero after cascade deletion",
    deletedArticle.comment_count,
    0,
  );

  // Step 11: Verify view count cleared
  TestValidator.equals(
    "article view_count reset to zero after cascade deletion",
    deletedArticle.view_count,
    0,
  );

  // Step 12: Verify attachments cleared
  TestValidator.predicate(
    "attachments removed in cascade deletion",
    deletedArticle.attachments === undefined ||
      deletedArticle.attachments.length === 0,
  );

  // Step 13: Verify complete cascade deletion lifecycle
  TestValidator.predicate(
    "cascade deletion properly handled all associated data",
    deletedArticle.status === "deleted" &&
      deletedArticle.comment_count === 0 &&
      deletedArticle.view_count === 0 &&
      (deletedArticle.attachments === undefined ||
        deletedArticle.attachments.length === 0) &&
      deletedArticle.deleted_at !== null &&
      deletedArticle.deleted_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticle";
import type { IDiscussionBoardArticleAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleAttachment";
import type { IDiscussionBoardArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardArticleCategory";
import type { IDiscussionBoardContributor } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardContributor";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that article metadata is properly updated during deletion.
 *
 * Creates an article with specific content, title, category, and timestamps.
 * Deletes the article and verifies that:
 *
 * - The deleted_at timestamp is set
 * - The updated_at timestamp reflects the deletion time
 * - The status field changes to 'deleted'
 * - The article retains all original content and author information for audit
 *   purposes
 * - The response includes complete article data with deletion metadata intact
 */
export async function test_api_article_deletion_updates_metadata(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate as a contributor
  const contributor: IDiscussionBoardContributor.IAuthorized =
    await api.functional.auth.contributor.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        username: RandomGenerator.alphaNumeric(10),
        password: "TestPassword123!",
        href: "https://example.com/register",
        referrer: "https://example.com",
      } satisfies IDiscussionBoardContributor.ICreate,
    });
  typia.assert(contributor);
  TestValidator.predicate(
    "contributor is authenticated",
    contributor.id.length > 0,
  );
  TestValidator.equals(
    "contributor account status",
    contributor.account_status,
    "active",
  );

  // Step 2: Create an article with specific metadata
  const articleTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 2,
    wordMax: 5,
  });
  const articleContent = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 5,
    sentenceMax: 10,
  });

  const article: IDiscussionBoardArticle =
    await api.functional.discussionBoard.contributor.articles.create(
      connection,
      {
        body: {
          title: articleTitle,
          content: articleContent,
          categoryId: typia.random<string & tags.Format<"uuid">>(),
          href: "https://example.com/articles/create",
          referrer: "https://example.com/articles",
        } satisfies IDiscussionBoardArticle.ICreate,
      },
    );
  typia.assert(article);

  // Verify article was created correctly
  TestValidator.equals(
    "article author ID matches",
    article.author.id,
    contributor.id,
  );
  TestValidator.equals("article title matches", article.title, articleTitle);
  TestValidator.equals(
    "article content matches",
    article.content,
    articleContent,
  );
  TestValidator.equals("article status is draft", article.status, "draft");
  TestValidator.predicate(
    "deleted_at is null on creation",
    article.deleted_at === null || article.deleted_at === undefined,
  );

  const createdAtTime = new Date(article.created_at);
  const updatedAtTime = new Date(article.updated_at);
  TestValidator.predicate(
    "created_at and updated_at are set",
    createdAtTime.getTime() <= updatedAtTime.getTime(),
  );

  // Step 3: Delete the article
  const beforeDeletion = new Date();
  const deletedArticle: IDiscussionBoardArticle =
    await api.functional.discussionBoard.contributor.articles.erase(
      connection,
      {
        articleId: article.id,
      },
    );
  const afterDeletion = new Date();
  typia.assert(deletedArticle);

  // Step 4: Verify deletion metadata
  TestValidator.equals(
    "deleted article ID matches original",
    deletedArticle.id,
    article.id,
  );
  TestValidator.equals(
    "deleted article status is deleted",
    deletedArticle.status,
    "deleted",
  );
  TestValidator.equals(
    "deleted article title preserved",
    deletedArticle.title,
    articleTitle,
  );
  TestValidator.equals(
    "deleted article content preserved",
    deletedArticle.content,
    articleContent,
  );
  TestValidator.equals(
    "deleted article author preserved",
    deletedArticle.author.id,
    contributor.id,
  );

  // Verify deleted_at timestamp is set and recent
  TestValidator.predicate(
    "deleted_at timestamp is set",
    deletedArticle.deleted_at !== null &&
      deletedArticle.deleted_at !== undefined,
  );

  if (deletedArticle.deleted_at) {
    const deletedAtTime = new Date(deletedArticle.deleted_at);
    TestValidator.predicate(
      "deleted_at is within 60 seconds of deletion",
      deletedAtTime.getTime() >= beforeDeletion.getTime() - 1000 &&
        deletedAtTime.getTime() <= afterDeletion.getTime() + 1000,
    );
  }

  // Verify updated_at timestamp reflects deletion
  const updatedAtAfterDeletion = new Date(deletedArticle.updated_at);
  TestValidator.predicate(
    "updated_at reflects deletion time",
    updatedAtAfterDeletion.getTime() >= beforeDeletion.getTime() - 1000 &&
      updatedAtAfterDeletion.getTime() <= afterDeletion.getTime() + 1000,
  );

  // Verify category is preserved
  TestValidator.predicate(
    "category is preserved in deleted article",
    deletedArticle.category !== null && deletedArticle.category !== undefined,
  );
}

